#!/bin/bash
set -euo pipefail

awk -F'\t' '
BEGIN {
    tot_units = 0
    tot_rev = 0
}
NR > 1 {
    r = $1
    u = $3 + 0
    p = $4 + 0
    rev_row = u * p
    units[r] += u
    rev[r] += rev_row
    tot_units += u
    tot_rev += rev_row
}
END {
    printf "%-8s %6s %10s\n", "REGION", "UNITS", "REVENUE"

    n = 0
    for (r in units) {
        reg[n] = r
        n++
    }

    for (i = 0; i < n; i++) {
        best = i
        for (j = i + 1; j < n; j++) {
            rj = reg[j]
            rb = reg[best]
            diff = rev[rj] - rev[rb]
            if (diff > 0.0001) {
                best = j
            } else if (diff >= -0.0001 && rj < rb) {
                best = j
            }
        }
        if (best != i) {
            tmp = reg[i]
            reg[i] = reg[best]
            reg[best] = tmp
        }
    }

    for (i = 0; i < n; i++) {
        r = reg[i]
        printf "%-8s %6d %10.2f\n", r, units[r], rev[r]
    }

    printf "--------------------------\n"
    printf "%-8s %6d %10.2f\n", "TOTAL", tot_units, tot_rev
}
' /home/eval/data/sales.tsv > /home/eval/data/report.txt

exit 0
